// Merge URLs, Topics, and Locations data
const topicList = $('Read Topics from Sheet').all().map(item => {
  return item.json.topic || item.json.Topic || Object.values(item.json)[0];
}).filter(topic => topic && topic.trim() !== '');

const locationList = $('Read Locations from Sheet').all().map(item => {
  return item.json.location || item.json.Location || Object.values(item.json)[0];
}).filter(loc => loc && loc.trim() !== '');

const urlList = $('Read URLs from Sheet').all().map(item => {
  return {
    url: item.json.url || item.json.URL || Object.values(item.json)[0],
    name: item.json.name || item.json.Name || Object.values(item.json)[1] || 'Unknown',
    maxPages: parseInt(item.json.max_pages || item.json.maxPages || 3),
    delayMs: parseInt(item.json.delay_ms || item.json.delayMs || 2000)
  };
}).filter(item => item.url && item.url.trim() !== '');

return {
  json: {
    urls: urlList,
    topics: topicList,
    locations: locationList,
    topicsString: topicList.join(', '),
    locationsString: locationList.join(', ')
  }
};

// Pagination handler - generates URLs for multiple pages
const baseUrl = $input.item.json.url;
const maxPages = $input.item.json.maxPages || 3;
const name = $input.item.json.name;
const delayMs = $input.item.json.delayMs || 2000;
const topics = $input.item.json.topics;
const locations = $input.item.json.locations;

const pageUrls = [];

// Detect site type and generate paginated URLs
if (baseUrl.includes('meetup.com')) {
  // Meetup pagination: uses offset parameter
  for (let i = 0; i < maxPages; i++) {
    const offset = i * 20;
    let url = baseUrl;
    if (url.includes('?')) {
      url += `&offset=${offset}`;
    } else {
      url += `?offset=${offset}`;
    }
    pageUrls.push({
      url: url,
      page: i + 1,
      name: name,
      delayMs: delayMs,
      topics: topics,
      locations: locations,
      siteType: 'meetup'
    });
  }
} else if (baseUrl.includes('eventbrite.com')) {
  // Eventbrite pagination: uses page parameter
  for (let i = 1; i <= maxPages; i++) {
    let url = baseUrl;
    if (url.includes('?')) {
      url += `&page=${i}`;
    } else {
      url += `?page=${i}`;
    }
    pageUrls.push({
      url: url,
      page: i,
      name: name,
      delayMs: delayMs,
      topics: topics,
      locations: locations,
      siteType: 'eventbrite'
    });
  }
} else {
  // Generic - just scrape the single URL
  pageUrls.push({
    url: baseUrl,
    page: 1,
    name: name,
    delayMs: delayMs,
    topics: topics,
    locations: locations,
    siteType: 'generic'
  });
}

return pageUrls.map(p => ({ json: p }));

// Enhanced event extraction with location awareness
const responseData = $input.item.json;
const html = responseData.body || responseData.data || '';
const statusCode = responseData.statusCode;
const url = $('Anti-Rate-Limit Delay').item.json.url;
const page = $('Anti-Rate-Limit Delay').item.json.page;
const name = $('Anti-Rate-Limit Delay').item.json.name;
const topics = $('Anti-Rate-Limit Delay').item.json.topics;
const locations = $('Anti-Rate-Limit Delay').item.json.locations;
const siteType = $('Anti-Rate-Limit Delay').item.json.siteType;

// Check for anti-bot blocks
function detectBlock(html, statusCode) {
  const blockIndicators = [
    'captcha',
    'challenge-running',
    'cf-browser-verification',
    'ray id',
    'access denied',
    'please verify',
    'bot detection',
    'security check'
  ];

  const lowerHtml = html.toLowerCase();

  if (statusCode === 403 || statusCode === 429 || statusCode === 503) {
    return { blocked: true, reason: `HTTP ${statusCode} - Rate limited or blocked` };
  }

  for (const indicator of blockIndicators) {
    if (lowerHtml.includes(indicator)) {
      return { blocked: true, reason: `Anti-bot protection detected: ${indicator}` };
    }
  }

  return { blocked: false, reason: null };
}

// Strip HTML and clean text
function stripHtml(html) {
  if (!html) return '';

  let text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  text = text.replace(/<[^>]+>/g, ' ');
  text = text.replace(/&nbsp;/g, ' ');
  text = text.replace(/&amp;/g, '&');
  text = text.replace(/&lt;/g, '<');
  text = text.replace(/&gt;/g, '>');
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");
  text = text.replace(/&#(\d+);/g, (match, dec) => String.fromCharCode(dec));
  text = text.replace(/\s+/g, ' ');

  return text.trim();
}

// Extract location from text
function extractLocation(text) {
  // Common location patterns
  const locationPatterns = [
    /(?:location|venue|place|address|where)[:\s]+([^.\n]{5,100})/gi,
    /(?:at|in)\s+((?:[A-Z][a-z]+\s*)+(?:,\s*[A-Z]{2})?)/g,
    /([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*,\s*[A-Z]{2}\s*\d{5})/g,
    /(\d+\s+[A-Z][a-z]+\s+(?:Street|St|Avenue|Ave|Boulevard|Blvd|Road|Rd|Drive|Dr|Lane|Ln)[^.\n]{0,50})/gi
  ];

  const foundLocations = [];

  for (const pattern of locationPatterns) {
    let match;
    while ((match = pattern.exec(text)) !== null) {
      const loc = match[1].trim();
      if (loc.length > 3 && loc.length < 150) {
        foundLocations.push(loc);
      }
    }
  }

  return foundLocations;
}

// Extract events with location filtering
function extractEvents(text, topics, targetLocations) {
  const events = [];
  const sentences = text.split(/[.!?]+/);

  const eventKeywords = [
    'event', 'conference', 'meeting', 'workshop', 'seminar', 'webinar',
    'summit', 'forum', 'symposium', 'exhibition', 'fair', 'festival',
    'ceremony', 'celebration', 'gathering', 'session', 'presentation',
    'meetup', 'hackathon', 'bootcamp', 'networking', 'talk', 'lecture',
    'date', 'when', 'where', 'time', 'location', 'venue', 'schedule',
    'rsvp', 'register', 'join us', 'attend',
    'january', 'february', 'march', 'april', 'may', 'june',
    'july', 'august', 'september', 'october', 'november', 'december',
    'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday',
    '2024', '2025', '2026'
  ];

  // Date extraction patterns
  const datePatterns = [
    /(\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4})/g,
    /((?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{1,2}(?:st|nd|rd|th)?(?:,?\s*\d{4})?)/gi,
    /(\d{1,2}(?:st|nd|rd|th)?\s+(?:of\s+)?(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*(?:,?\s*\d{4})?)/gi
  ];

  sentences.forEach(sentence => {
    const lowerSentence = sentence.toLowerCase();

    const hasEventKeyword = eventKeywords.some(keyword => 
      lowerSentence.includes(keyword)
    );

    const relatedTopics = topics.filter(topic => 
      lowerSentence.includes(topic.toLowerCase())
    );

    // Check for location match
    const sentenceLocations = extractLocation(sentence);
    const matchedLocations = [];

    if (targetLocations.length > 0) {
      // Check if any target location is mentioned
      for (const targetLoc of targetLocations) {
        if (lowerSentence.includes(targetLoc.toLowerCase())) {
          matchedLocations.push(targetLoc);
        }
        // Also check extracted locations
        for (const foundLoc of sentenceLocations) {
          if (foundLoc.toLowerCase().includes(targetLoc.toLowerCase())) {
            matchedLocations.push(foundLoc);
          }
        }
      }
    }

    // Extract dates from sentence
    const dates = [];
    for (const pattern of datePatterns) {
      let match;
      while ((match = pattern.exec(sentence)) !== null) {
        dates.push(match[1]);
      }
    }

    // Event must have keyword AND topic match
    // If locations are specified, must also match location
    const locationMatch = targetLocations.length === 0 || matchedLocations.length > 0;

    if (hasEventKeyword && relatedTopics.length > 0 && locationMatch && sentence.trim().length > 20) {
      events.push({
        text: sentence.trim(),
        relatedTopics: relatedTopics,
        matchedLocations: matchedLocations.length > 0 ? matchedLocations : sentenceLocations,
        extractedDates: dates,
        confidence: relatedTopics.length > 1 ? 'high' : 'medium'
      });
    }
  });

  return events;
}

// Check for blocking
const blockStatus = detectBlock(html, statusCode);

if (blockStatus.blocked) {
  return {
    json: {
      sourceUrl: url,
      sourceName: name,
      page: page,
      siteType: siteType,
      blocked: true,
      blockReason: blockStatus.reason,
      eventsFound: 0,
      events: [],
      scrapedAt: new Date().toISOString(),
      topics: topics,
      locations: locations
    }
  };
}

// Clean HTML and extract events
const cleanText = stripHtml(html);
const extractedEvents = extractEvents(cleanText, topics, locations);

return {
  json: {
    sourceUrl: url,
    sourceName: name,
    page: page,
    siteType: siteType,
    blocked: false,
    blockReason: null,
    eventsFound: extractedEvents.length,
    events: extractedEvents,
    scrapedAt: new Date().toISOString(),
    topics: topics,
    locations: locations,
    contentPreview: cleanText.substring(0, 500) + '...'
  }
};
